class Solution {
  public int earliestFinishTime(
      int[] landStartTime, int[] landDuration, int[] waterStartTime, int[] waterDuration) {
    return Math.min(
        best(landStartTime, landDuration, waterStartTime, waterDuration),
        best(waterStartTime, waterDuration, landStartTime, landDuration));
  }

  // earliest finish when a ride from (s1, d1) is taken first, then one from (s2, d2)
  private int best(int[] s1, int[] d1, int[] s2, int[] d2) {
    int best = Integer.MAX_VALUE;
    for (int i = 0; i < s1.length; i++) {
      int t = s1[i] + d1[i];
      for (int j = 0; j < s2.length; j++) {
        best = Math.min(best, Math.max(t, s2[j]) + d2[j]);
      }
    }
    return best;
  }
}
